function cleanEmail(e){
  e = String(e || '').toLowerCase().trim();
  // basic format check
  if(!/^[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}$/.test(e)) return '';
  // obvious junk / false-positive domains
  if(/@(2x|3x|sentry|wixpress|example|godaddy|domain|email)\./.test(e)) return '';
  // false matches ending in an image/asset extension
  if(/\.(png|jpg|jpeg|gif|webp|svg|css|js)$/.test(e)) return '';
  return e;
}
let places = [];
for (const item of $input.all()) {
  if (Array.isArray(item.json)) places.push(...item.json);
  else if (Array.isArray(item.json.data)) places.push(...item.json.data);
  else places.push(item.json);
}
const out = [];
const seen = new Set();
for (const p of places) {
  // LIST CLEANUP: drop non-dental places (e.g. Park Veterinary Group)
  const kimlik = ((p.categoryName || '') + ' ' + (p.title || '')).toLowerCase();
  if (!/dent|orthodont|implantolog/.test(kimlik)) continue;
  if (/veterinar|animal|\bpet\b/.test(kimlik)) continue;
  // ---- TARGET SEGMENT: mid-size private UK dental clinic ----
  // Budget is 15 leads a day; the rules below drop candidates that would score <=45
  // before they ever reach the (paid) scoring step.
  if (!String(p.website || '').trim()) continue;              // no website -> nothing to score
  if (/\bnhs\b/.test(kimlik)) continue;                       // NHS-only -> cannot set its own prices
  if (Number(p.reviewsCount || 0) < 8) continue;              // dead or single-room listing
  let raw = '';
  if (Array.isArray(p.emails) && p.emails.length) raw = p.emails[0];
  else if (p.contactDetails && Array.isArray(p.contactDetails.emails) && p.contactDetails.emails.length) raw = p.contactDetails.emails[0];
  const email = cleanEmail(raw);
  if (!email) continue;            // invalid/junk email -> drop
  if (seen.has(email)) continue;   // duplicate within this run -> drop
  seen.add(email);
  out.push({ json: {
    Business_Name: p.title || '', Website: p.website || '', Email: email,
    Category: p.categoryName || '', Rating: (p.totalScore != null ? p.totalScore : ''),
    Review_Count: (p.reviewsCount != null ? p.reviewsCount : ''), Address: p.address || ''
  }});
}
return out;

let ai = {};
try { ai = JSON.parse($json.choices[0].message.content); } catch (e) { ai = {}; }
const c = $('Prepare Leads').item.json;
return { json: {
  Business_Name: c.Business_Name,
  Website: c.Website,
  Email: c.Email,
  Status: 'Awaiting Email',
  opening_line: ai.opening_line || '',
  main_treatments: ai.main_treatments || '',
  gap_summary: ai.gap_summary || '',
  Lead_Score: (ai.lead_score != null ? ai.lead_score : ''),
  Gap_Verified: (ai.gap_verified === true ? 'YES' : 'NO')
} };

const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const rows = $input.all().map(i => i.json);
const n = rows.length;
const valid = rows.filter(r => r.Lead_Score !== '' && !isNaN(Number(r.Lead_Score)));
const scores = valid.map(r => Number(r.Lead_Score));
const avg = scores.length ? Math.round(scores.reduce((a,b)=>a+b,0)/scores.length) : 0;
const high = valid.filter(r => Number(r.Lead_Score) >= 80).length;
const sorted = valid.slice().sort((a,b)=>Number(b.Lead_Score)-Number(a.Lead_Score));
const top3 = sorted.slice(0,3).map((r,i)=> (i+1)+'. '+esc(r.Business_Name)+' · '+r.Lead_Score).join('\n');
const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const d = new Date();
const date = d.getDate()+' '+months[d.getMonth()]+' '+d.getFullYear();
const text =
  '<b>YourBrand — Daily Lead Report</b>\n' + date + '\n' +
  '──────────────\n' +
  'New qualified clinics: <b>' + n + '</b>\n' +
  'Average lead score: <b>' + avg + '/100</b>\n' +
  'High potential (80+): <b>' + high + '</b>\n\n' +
  '<b>Top opportunities</b>\n' + (top3 || '—') + '\n' +
  '──────────────\n' +
  'Status: all "Awaiting Email", handed to the outreach workflow';
return [{ json: { report: text, count: n } }];
